// AccessLogEntry defines model for AccessLogEntry.
type AccessLogEntry struct {
	// Action create, read, update, delete, accept or revoke.
	//
	// Example: read
	Action string `json:"action"`

	// ActorId Absent when the person was removed.
	ActorId   *openapi_types.UUID `json:"actorId,omitempty"`
	ActorName string              `json:"actorName"`

	// ActorRole Any person who can act in the family, parents and caregivers.
	ActorRole *PersonRole `json:"actorRole,omitempty"`
	At        time.Time   `json:"at"`

	// Entity snake_case entity name, as in the audit log.
	//
	// Example: child_passport
	Entity   string  `json:"entity"`
	EntityId *string `json:"entityId,omitempty"`
	Id       string  `json:"id"`
}

// AccessLogList defines model for AccessLogList.
type AccessLogList struct {
	// Items Newest first.
	Items []AccessLogEntry `json:"items"`
}

// AgendaSuggestion defines model for AgendaSuggestion.
type AgendaSuggestion struct {
	// DiaryEntryId The newest of the parent's matching entries that has no agenda topic yet; the topic goes on this entry.
	DiaryEntryId openapi_types.UUID `json:"diaryEntryId"`

	// Reason Why it is suggested, counting entries only.
	//
	// Example: You wrote about sleep in 2 entries this week.
	Reason string `json:"reason"`

	// Text Example: Sleep lately
	Text string `json:"text"`
}

// AgendaTopic defines model for AgendaTopic.
type AgendaTopic struct {
	AddedAt time.Time `json:"addedAt"`

	// DiaryEntryId Set when the topic came from one of the parent's diary entries (DiaryEntry.agendaTopic).
	DiaryEntryId *openapi_types.UUID `json:"diaryEntryId,omitempty"`
	Id           openapi_types.UUID  `json:"id"`

	// Text The topic the parent chose, never the entry text.
	Text string `json:"text"`
}

// Allergy defines model for Allergy.
type Allergy struct {
	// Certainty confirmed = diagnosed by a clinician; suspected = noticed at home, not yet tested.
	Certainty AllergyCertainty    `json:"certainty"`
	Id        openapi_types.UUID  `json:"id"`
	NotedOn   *openapi_types.Date `json:"notedOn,omitempty"`

	// Reaction Example: Hives within minutes
	Reaction *string `json:"reaction,omitempty"`

	// Substance Example: Peanut
	Substance string `json:"substance"`

	// Visibility Who besides the author may see a sensitive record.
	// private = author only; partner = author and the other parent;
	// care_team = author and their professionals, not the partner; family = both parents.
	Visibility Visibility `json:"visibility"`
}

